import { Router, type IRouter } from "express";
import { db } from "@workspace/db";
import { productsTable, categoriesTable } from "@workspace/db/schema";
import { eq, ilike, and, or, sql, count, isNotNull, asc, desc, type SQL } from "drizzle-orm";

const router: IRouter = Router();

// Show only products with an image; hide products priced $0.01–$34.99 (shown as "Email for Details" if $35–$49.99 or $0)
const visiblePrice = sql`(${productsTable.price}::numeric = 0 OR ${productsTable.price}::numeric >= 35)`;

// ---------------------------------------------------------------------------
// Search synonym / alias normalization
// Maps user-facing terms → the actual words that appear in product names.
// Longer/more-specific phrases must come before shorter ones so they match first.
// ---------------------------------------------------------------------------
const SEARCH_ALIASES: Array<[RegExp, string]> = [
  // Lock types → "lock"
  [/^sash locks?$/i,        "lock"],
  [/^cam locks?$/i,         "lock"],
  [/^sweep locks?$/i,       "lock"],
  [/^window locks?$/i,      "lock"],
  // Keeper
  [/^lock keeper(?:s)?$/i,      "keeper"],
  // Latch types → "latch"
  [/^tilt latch(?:es)?$/i,      "latch"],
  [/^window latch(?:es)?$/i,    "latch"],
  // Operator / crank
  [/^window cranks?$/i,     "operator"],
  [/^cranks?$/i,            "operator"],
  // Balance types → "balance"
  [/^channel balances?$/i,  "balance"],
  [/^window balances?$/i,   "balance"],
  // Roller types → "roller"
  [/^patio door rollers?$/i, "roller"],
];

// Terms that map to a category filter rather than a text search
const CATEGORY_ALIASES: Array<[RegExp, string]> = [
  [/^weather\s?strips?$/i,   "Window Glazing and Weatherstrip"],
  [/^weatherstripping$/i,    "Window Glazing and Weatherstrip"],
  [/^seals?$/i,              "Window Glazing and Weatherstrip"],
];

/**
 * Normalise a raw search string.
 * Returns { search, category } where one or both may be undefined.
 * If the term maps to a category, search is cleared and category is set.
 */
function normalizeSearch(raw: string | undefined, existingCategory: string | undefined): { search?: string; category?: string } {
  if (!raw || !raw.trim()) return { category: existingCategory };

  const term = raw.trim();

  // Check category aliases first
  for (const [pattern, cat] of CATEGORY_ALIASES) {
    if (pattern.test(term)) return { category: cat };
  }

  // Check search aliases
  for (const [pattern, canonical] of SEARCH_ALIASES) {
    if (pattern.test(term)) return { search: canonical, category: existingCategory };
  }

  // No alias match — return as-is
  return { search: term, category: existingCategory };
}

function toNumber(val: string | undefined, fallback: number): number {
  const n = Number(val);
  return isNaN(n) ? fallback : n;
}

router.get("/products/featured", async (req, res) => {
  try {
    const featured = await db
      .select()
      .from(productsTable)
      .where(and(
        eq(productsTable.inStock, true),
        isNotNull(productsTable.imageUrl),
        sql`${productsTable.price}::numeric >= 50`
      ))
      .orderBy(sql`RANDOM()`)
      .limit(8);
    res.json(featured);
  } catch (err) {
    req.log.error({ err }, "Error fetching featured products");
    res.status(500).json({ error: "internal_error", message: "Failed to fetch featured products" });
  }
});

router.get("/products/search-suggestions", async (req, res) => {
  try {
    const rawQ = String(req.query.q || "");
    if (!rawQ || rawQ.length < 2) {
      res.json([]);
      return;
    }

    const { search: q, category } = normalizeSearch(rawQ, undefined);

    // If aliased to a category, return representative product names from that category
    if (!q && category) {
      const results = await db
        .select({ name: productsTable.name })
        .from(productsTable)
        .where(and(isNotNull(productsTable.imageUrl), visiblePrice, eq(productsTable.category, category)))
        .limit(8);
      res.json(results.map((r) => r.name));
      return;
    }

    const results = await db
      .select({ name: productsTable.name })
      .from(productsTable)
      .where(and(isNotNull(productsTable.imageUrl), visiblePrice, ilike(productsTable.name, `%${q}%`)))
      .limit(8);
    res.json(results.map((r) => r.name));
  } catch (err) {
    req.log.error({ err }, "Error fetching search suggestions");
    res.status(500).json({ error: "internal_error", message: "Failed to fetch suggestions" });
  }
});

// GET /api/products/:sku/variants — sibling variants sharing the same variantGroupId
// Deduplicates by variant_label (one representative SKU per unique label),
// sorted numerically by the leading measurement if present.
router.get("/products/:sku/variants", async (req, res) => {
  try {
    const { sku } = req.params;
    const [product] = await db
      .select({ variantGroupId: productsTable.variantGroupId })
      .from(productsTable)
      .where(eq(productsTable.sku, sku))
      .limit(1);

    if (!product?.variantGroupId) {
      res.json({ variants: [] });
      return;
    }

    // Deduplicate by variant_label: pick one representative SKU per label.
    // Sort numerically by leading measurement (e.g. "10in" < "11in" < "100in")
    // then fall back to label text for non-numeric labels.
    const rows = await db.execute(sql`
      SELECT DISTINCT ON (COALESCE(variant_label, sku))
        sku,
        name,
        variant_label AS "variantLabel",
        price,
        in_stock AS "inStock",
        image_url AS "imageUrl"
      FROM products
      WHERE variant_group_id = ${product.variantGroupId}
      ORDER BY
        COALESCE(variant_label, sku),
        CASE
          WHEN variant_label ~ '^[0-9]'
          THEN (REGEXP_MATCH(variant_label, '^([0-9]+)'))[1]::integer
          ELSE NULL
        END NULLS LAST,
        variant_label
    `);

    // Re-sort the deduplicated set numerically in JS for precision
    type VariantRow = { sku: string; name: string; variantLabel: string | null; price: string; inStock: boolean; imageUrl: string | null };
    const variants: VariantRow[] = (rows.rows as unknown as VariantRow[]).sort((a, b) => {
      const aLabel = a.variantLabel ?? a.name;
      const bLabel = b.variantLabel ?? b.name;
      const aNum = parseFloat(aLabel.replace(/[^0-9.]/g, "") || "0");
      const bNum = parseFloat(bLabel.replace(/[^0-9.]/g, "") || "0");
      if (!isNaN(aNum) && !isNaN(bNum) && aNum !== bNum) return aNum - bNum;
      return aLabel.localeCompare(bLabel);
    });

    res.json({ variants });
  } catch (err) {
    req.log.error({ err }, "Error fetching product variants");
    res.status(500).json({ error: "internal_error", message: "Failed to fetch variants" });
  }
});

router.get("/products/:sku", async (req, res) => {
  try {
    const { sku } = req.params;
    const [product] = await db
      .select()
      .from(productsTable)
      .where(eq(productsTable.sku, sku))
      .limit(1);
    if (!product) {
      res.status(404).json({ error: "not_found", message: "Product not found" });
      return;
    }
    res.json(product);
  } catch (err) {
    req.log.error({ err }, "Error fetching product by SKU");
    res.status(500).json({ error: "internal_error", message: "Failed to fetch product" });
  }
});

router.get("/products", async (req, res) => {
  try {
    const { page: pageStr, limit: limitStr, sort } = req.query as Record<string, string | undefined>;
    const page = toNumber(pageStr, 1);
    const limit = Math.min(toNumber(limitStr, 24), 100);
    const offset = (page - 1) * limit;

    // Normalize search term — resolves aliases/synonyms to actual catalog terms
    const rawCategory = req.query.category as string | undefined;
    const rawSearch   = req.query.search   as string | undefined;
    const { search, category } = normalizeSearch(rawSearch, rawCategory);

    // Only show in-stock products; hide products priced $0.01–$34.99
    const conditions = [eq(productsTable.inStock, true), visiblePrice];
    if (category) conditions.push(eq(productsTable.category, category));
    if (search) {
      conditions.push(
        or(
          ilike(productsTable.name, `%${search}%`),
          ilike(productsTable.description, `%${search}%`),
          ilike(productsTable.sku, `%${search}%`)
        )
      );
    }

    const minPrice = req.query.minPrice ? Number(req.query.minPrice) : null;
    const maxPrice = req.query.maxPrice ? Number(req.query.maxPrice) : null;
    if (minPrice !== null && !isNaN(minPrice)) {
      conditions.push(sql`${productsTable.price}::numeric >= ${minPrice}`);
    }
    if (maxPrice !== null && !isNaN(maxPrice)) {
      conditions.push(sql`${productsTable.price}::numeric <= ${maxPrice}`);
    }

    const whereClause = and(...conditions) as SQL;

    // Determine sort order
    // Default "newest" puts imaged products first, then sorts by newest ID within each group
    const hasImage = sql`CASE WHEN ${productsTable.imageUrl} IS NOT NULL AND ${productsTable.imageUrl} != '' THEN 0 ELSE 1 END`;

    // Dedup mode: return one canonical product per variant group (with variant count)
    const dedup = req.query.dedup === "true";
    if (dedup) {
      const innerOrder =
        sort === "price-asc"  ? sql`price::numeric ASC NULLS LAST`
        : sort === "price-desc" ? sql`price::numeric DESC NULLS FIRST`
        : sql`CASE WHEN image_url IS NOT NULL AND image_url != '' THEN 0 ELSE 1 END, id DESC`;

      const outerOrder =
        sort === "price-asc"  ? sql`price::numeric ASC NULLS LAST`
        : sort === "price-desc" ? sql`price::numeric DESC NULLS FIRST`
        : sort === "name-asc"   ? sql`name ASC`
        : sql`CASE WHEN image_url IS NOT NULL AND image_url != '' THEN 0 ELSE 1 END, id DESC`;

      const [dedupResult, countResult] = await Promise.all([
        db.execute(sql`
          SELECT * FROM (
            SELECT DISTINCT ON (COALESCE(variant_group_id, sku)) *,
              COUNT(*) OVER (PARTITION BY COALESCE(variant_group_id, sku))::int AS "variantCount"
            FROM products
            WHERE ${whereClause}
            ORDER BY COALESCE(variant_group_id, sku), ${innerOrder}
          ) deduped
          ORDER BY ${outerOrder}
          LIMIT ${limit} OFFSET ${offset}
        `),
        db.execute(sql`
          SELECT COUNT(*)::int AS count FROM (
            SELECT DISTINCT ON (COALESCE(variant_group_id, sku)) id
            FROM products
            WHERE ${whereClause}
            ORDER BY COALESCE(variant_group_id, sku)
          ) deduped
        `),
      ]);

      const total = Number((countResult.rows[0] as any)?.count ?? 0);
      // Raw SQL returns snake_case column names — remap to camelCase to match Drizzle ORM output
      const products = (dedupResult.rows as any[]).map((r) => ({
        id: r.id,
        sku: r.sku,
        name: r.name,
        description: r.description,
        price: r.price,
        originalPrice: r.original_price,
        category: r.category,
        subcategory: r.subcategory,
        supplier: r.supplier,
        inStock: r.in_stock,
        imageUrl: r.image_url,
        tags: r.tags,
        specifications: r.specifications,
        compatibleBrands: r.compatible_brands,
        variantGroupId: r.variant_group_id,
        variantLabel: r.variant_label,
        attributes: r.attributes,
        soldAs: r.sold_as,
        createdAt: r.created_at,
        variantCount: r.variantCount != null ? Number(r.variantCount) : 1,
      }));

      res.json({ products, total, page, limit, totalPages: Math.ceil(total / limit) });
      return;
    }

    const [products, totalResult] = await Promise.all([
      db.select().from(productsTable).where(whereClause).orderBy(
        ...(sort === "price-asc"  ? [asc(productsTable.price)]
          : sort === "price-desc" ? [desc(productsTable.price)]
          : sort === "name-asc"   ? [asc(productsTable.name)]
          : [hasImage, desc(productsTable.id)] as any) // default: images-first then newest
      ).limit(limit).offset(offset),
      db.select({ count: count() }).from(productsTable).where(whereClause),
    ]);

    const total = Number(totalResult[0]?.count ?? 0);

    res.json({
      products,
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit),
    });
  } catch (err) {
    req.log.error({ err }, "Error fetching products");
    res.status(500).json({ error: "internal_error", message: "Failed to fetch products" });
  }
});

router.get("/categories", async (req, res) => {
  try {
    const cats = await db.select().from(categoriesTable);
    const counts = await db
      .select({ category: productsTable.category, count: count() })
      .from(productsTable)
      .where(and(eq(productsTable.inStock, true), visiblePrice))
      .groupBy(productsTable.category);

    const countMap = new Map(counts.map((c) => [c.category, Number(c.count)]));
    const result = cats.map((cat) => ({
      ...cat,
      productCount: countMap.get(cat.name) ?? 0,
    }));
    res.json(result);
  } catch (err) {
    req.log.error({ err }, "Error fetching categories");
    res.status(500).json({ error: "internal_error", message: "Failed to fetch categories" });
  }
});

router.get("/catalog/stats", async (req, res) => {
  try {
    const [totalProducts, totalCategories, supplierCounts, categoryCounts] = await Promise.all([
      db.select({ count: count() }).from(productsTable),
      db.select({ count: count() }).from(categoriesTable),
      db
        .select({ supplier: productsTable.supplier, count: count() })
        .from(productsTable)
        .groupBy(productsTable.supplier),
      db
        .select({ category: productsTable.category, count: count() })
        .from(productsTable)
        .groupBy(productsTable.category)
        .orderBy(sql`count(*) DESC`)
        .limit(5),
    ]);

    res.json({
      totalProducts: Number(totalProducts[0]?.count ?? 0),
      totalCategories: Number(totalCategories[0]?.count ?? 0),
      supplierBreakdown: supplierCounts.map((s) => ({
        supplier: s.supplier,
        count: Number(s.count),
      })),
      topCategories: categoryCounts.map((c) => ({
        category: c.category,
        count: Number(c.count),
      })),
    });
  } catch (err) {
    req.log.error({ err }, "Error fetching catalog stats");
    res.status(500).json({ error: "internal_error", message: "Failed to fetch stats" });
  }
});

export default router;
