import nodemailer from "nodemailer";
import { getContactForwardEmails } from "./lib/notifyRecipients.js";

const FROM_EMAIL = "All Window Door Parts <info@allwindowdoorparts.com>";

function createTransport() {
  const host = process.env.SMTP_HOST;
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;
  if (!host || !user || !pass) {
    console.warn("[email] SMTP not configured — skipping order notification");
    return null;
  }
  const port   = parseInt(process.env.SMTP_PORT ?? "465", 10);
  const secure = process.env.SMTP_SECURE !== "false";
  return nodemailer.createTransport({ host, port, secure, auth: { user, pass }, tls: { rejectUnauthorized: true } });
}

interface OrderItem { name: string; sku: string; price: number; quantity: number; }
interface OrderEmailPayload {
  orderId: string;
  customerName: string;
  customerEmail: string;
  customerPhone?: string;
  shippingAddress?: { line1: string; line2?: string; city: string; state: string; postal_code: string; country: string; };
  items: OrderItem[];
  subtotal: string;
  total: string;
  paymentMethod: "stripe" | "paypal";
}

function fmtAddr(a?: OrderEmailPayload["shippingAddress"]): string {
  if (!a) return "Not provided";
  return [a.line1, a.line2, `${a.city}, ${a.state} ${a.postal_code}`, a.country].filter(Boolean).join("<br>");
}

